/**
 * עמודי נחיתה לקמפיינים (T-026): `/lp/[slug]`. noindex, מחוץ ל-sitemap.
 *
 * נוצר אוטומטית מ-`baram-team/clients/shelachem/lp/_source` (העתק המאושר לעמודים)
 * בתוספת מיפוי הטענות. כל משפט שמכיל טענה שיווקית עטוף ב-`g(claims, withClaim, neutral)`:
 * בפרודקשן מוצגת רק הגרסה הניטרלית עד שכל הטענות במשפט מאושרות ב-`CLAIM_APPROVALS`
 * (`neutral: null` = הפריט לא מוצג כלל). ראו `lp-claims.ts`.
 */
import { gated as g, type ClaimId, type Gated } from "./lp-claims";

export interface LpRow {
  title: string;
  description: string;
  href?: string;
}
export interface LpFaq {
  question: string;
  answer: string;
}
export interface LpStat {
  value: string;
  label: string;
}
export type LpImageSection = "hero" | "pain" | "steps" | "eligibility" | "why";
export interface LpImageSlot {
  /** מזהה TODO לתמונה שעוד לא הופקה. */
  id: string;
  /** נתיב היעד המתוכנן לקובץ. */
  src: string;
  alt: string;
  section: LpImageSection;
  ratio: string;
  /** צילום קיים באתר שאפשר להשתמש בו במקום הפקה חדשה. */
  reuse?: string;
}
export interface LandingPage {
  slug: string;
  /** שם פנימי (קבוצת המודעות). */
  name: string;
  adGroups: string[];
  /** נושא שמוזן לטופס (`presetTopic`). */
  topic: string;
  /** עמוד התוכן הקשור באתר. */
  relatedHref: string;
  /** עמוד הגמלה הרלוונטי באתר ביטוח לאומי. */
  btlUrl: string;
  /** טענה ברמת העמוד: כל העמוד לא יוצג בפרודקשן עד שתאושר. */
  pageClaims: ClaimId[];
  metaTitle: Gated<string>;
  metaDescription: Gated<string>;
  h1: { title: string; strong: string };
  intro: Gated<string>;
  /** כותרת כרטיס הטופס (`**...**` = הדגשה). */
  formTitle: Gated<string>;
  submitLabel: string;
  pain: { heading: Gated<string>; items: Gated<LpRow>[]; close: Gated<string> };
  steps: Gated<LpRow>[];
  eligibility: {
    heading: Gated<string>;
    intro: Gated<string>;
    items: Gated<LpRow>[];
    note?: string;
    tip: Gated<string>;
  };
  midCta: { text: Gated<string>; button: string };
  faq: Gated<LpFaq>[];
  finalCta: { heading: Gated<string>; subtitle: Gated<string> };
  images: LpImageSlot[];
}

